import argparse
import json
import os
import subprocess
import sys
import time
from datetime import datetime
import requests

def load_config(config_path):
    try:
        with open(config_path, 'r') as f:
            return json.load(f)
    except (FileNotFoundError, json.JSONDecodeError) as e:
        print(f"ERROR: {str(e)}")
        sys.exit(1)

def get_build_id(url, timeout=10):
    try:
        response = requests.get(url, timeout=timeout)
        response.raise_for_status()
        data = response.json()
        if not isinstance(data, dict) or 'build_id' not in data or not isinstance(data['build_id'], str):
            print("ERROR: Invalid response format")
            sys.exit(1)
        return data['build_id']
    except requests.exceptions.RequestException as e:
        print(f"ERROR: HTTP request failed: {str(e)}")
        sys.exit(1)

def run_command(command):
    try:
        result = subprocess.run(command, shell=True, check=True, text=True)
        return result.returncode == 0, result.stdout
    except subprocess.CalledProcessError as e:
        print(f"ERROR: Command failed with exit code {e.returncode}")
        sys.exit(1)

def log_message(log_path, timestamp, tag, message):
    try:
        with open(log_path, 'a') as f:
            f.write(f"{timestamp} {tag} {message}\n")
    except IOError as e:
        print(f"{timestamp} ERROR {str(e)}")
        sys.exit(1)

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('config_path', type=str)
    args = parser.parse_args()

    config = load_config(args.config_path)
    url = config.get('url')
    command = config.get('command')
    state_path = config.get('state_path')
    log_path = config.get('log_path')

    if not all([url, command, state_path, log_path]):
        print("ERROR: Missing required configuration keys")
        sys.exit(1)

    try:
        build_id = get_build_id(url)
    except:
        sys.exit(1)

    current_build_id = None
    if os.path.exists(state_path):
        try:
            with open(state_path, 'r') as f:
                current_build_id = f.read().strip()
        except IOError:
            print("ERROR: Cannot read state file")
            sys.exit(1)

    if current_build_id != build_id:
        if not run_command(command):
            current_build_id = build_id
            try:
                with open(state_path, 'w') as f:
                    f.write(current_build_id)
            except IOError:
                print(f"{datetime.utcnow().isoformat() + 'Z' if datetime.utcnow().tzinfo else datetime.utcnow().isoformat()[:-3] + 'Z'} ERROR Cannot write state file")
                sys.exit(1)
        tag = "CHANGED"
        message = f"old={current_build_id if current_build_id else 'none'} new={build_id}"
    elif current_build_id == build_id:
        tag = "SAME"
        message = f"build_id={build_id}"
    else:
        tag = "ERROR"
        message = "State file mismatch"

    timestamp = datetime.utcnow().isoformat() + 'Z'
    log_message(log_path, timestamp, tag, message)
    print(f"{timestamp} {tag} {message}")

if __name__ == "__main__":
    main()

import json
import os
import sys
import requests
from datetime import datetime
import subprocess

def main():
    if len(sys.argv) != 2:
        print("ERROR: Missing CONFIG_PATH argument")
        sys.exit(1)

    config_path = sys.argv[1]
    try:
        with open(config_path, 'r') as f:
            config = json.load(f)
    except json.JSONDecodeError:
        print("ERROR: Invalid JSON in CONFIG_PATH")
        sys.exit(1)
    except IOError:
        print("ERROR: Failed to read CONFIG_PATH")
        sys.exit(1)

    if not all(key in config and isinstance(config[key], str) for key in ['url', 'command', 'state_path', 'log_path']):
        print("ERROR: Missing or invalid required keys in CONFIG_PATH")
        sys.exit(1)

    url = config['url']
    command = config['command']
    state_path = config['state_path']
    log_path = config['log_path']

    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()
        build_data = response.json()
    except requests.exceptions.RequestException as e:
        print(f"ERROR: Failed to fetch from {url}: {str(e)}")
        sys.exit(1)
    except ValueError:
        print("ERROR: Response from URL is not valid JSON")
        sys.exit(1)

    if 'build_id' not in build_data:
        print(f"ERROR: Response from URL missing 'build_id' field")
        sys.exit(1)

    new_build_id = build_data['build_id']
    old_build_id = None

    if os.path.exists(state_path):
        try:
            with open(state_path, 'r') as f:
                old_build_id = f.read().strip()
        except IOError:
            print(f"ERROR: Failed to read {state_path}")
            sys.exit(1)

    if old_build_id == new_build_id:
        tag = "SAME"
        message = f"build_id={new_build_id}"
    elif not os.path.exists(state_path):
        tag = "CHANGED"
        message = f"old=none new={new_build_id}"
    else:
        tag = "CHANGED"
        message = f"old={old_build_id} new={new_build_id}"

    try:
        if old_build_id != new_build_id or not os.path.exists(state_path):
            try:
                result = subprocess.run(command, shell=True, check=True, text=True, capture_output=True)
            except subprocess.CalledProcessError as e:
                tag = "ERROR"
                message = f"Command failed with exit code {e.returncode}: {e.stderr.strip()}"
            else:
                with open(state_path, 'w') as f:
                    f.write(new_build_id)
    except IOError as e:
        tag = "ERROR"
        message = f"Failed to write to {state_path}: {str(e)}"

    timestamp = datetime.utcnow().isoformat() + 'Z'
    log_entry = f"{timestamp} {tag} {message}"

    try:
        with open(log_path, 'a') as f:
            f.write(log_entry + '\n')
    except IOError:
        print(log_entry)
        sys.exit(1)

    print(log_entry)
    sys.exit(0)

if __name__ == "__main__":
    main()
